"use client"

import type { ColorFieldProps as ColorFieldPrimitiveProps } from "react-aria-components"
import { ColorField as ColorFieldPrimitive } from "react-aria-components"
import { twJoin } from "tailwind-merge"

import { composeTailwindRenderProps } from "@/registry/new-york-v4/lib/primitive"

import { ColorPicker } from "./color-picker"
import { ColorSwatch } from "./color-swatch"
import {
  Description,
  FieldError,
  FieldGroup,
  Input,
  Label,
  type FieldProps,
} from "./field"

interface ColorFieldProps extends ColorFieldPrimitiveProps, FieldProps {
  prefix?: React.ReactNode
  suffix?: React.ReactNode
  isLoading?: boolean
  enableColorPicker?: boolean
}

const ColorField = ({
  label,
  description,
  errorMessage,
  placeholder,
  prefix,
  suffix,
  isLoading,
  enableColorPicker = true,
  className,
  ...props
}: ColorFieldProps) => {
  const value = props.value ?? props.defaultValue
  return (
    <ColorFieldPrimitive
      {...props}
      aria-label={props["aria-label"] ?? "Color field"}
      className={composeTailwindRenderProps(
        className,
        "group flex w-full flex-col gap-y-1 **:data-[slot=color-swatch]:-ml-0.5 *:data-[slot=label]:font-medium"
      )}
    >
      {label && <Label>{label}</Label>}
      <FieldGroup data-loading={isLoading ? "true" : undefined}>
        {prefix && typeof prefix === "string" ? (
          <span className="text-muted-fg ml-2">{prefix}</span>
        ) : (
          prefix
        )}
        <div className={twJoin("flex w-full items-center", prefix && "ml-6")}>
          {value && (
            <span className="ml-1">
              {enableColorPicker ? (
                <ColorPicker
                  className="*:[button]:size-8 *:[button]:rounded-sm *:[button]:ring-0"
                  onChange={props.onChange}
                  defaultValue={value}
                />
              ) : (
                <ColorSwatch className="size-6" color={value.toString("hex")} />
              )}
            </span>
          )}

          <Input placeholder={placeholder} />
        </div>
        {suffix && typeof suffix === "string" ? (
          <span className="text-muted-fg mr-2">{suffix}</span>
        ) : (
          suffix
        )}
      </FieldGroup>
      {description && <Description>{description}</Description>}
      <FieldError>{errorMessage}</FieldError>
    </ColorFieldPrimitive>
  )
}

export { ColorField }
export type { ColorFieldProps }
